33	import static org.apache.hadoop.fs.CommonConfigurationKeysPublic.HADOOP_CALLER_CONTEXT_SEPARATOR_DEFAULT;
34	import static org.apache.hadoop.fs.CommonConfigurationKeysPublic.HADOOP_CALLER_CONTEXT_SEPARATOR_KEY;
35	
36	/**
37	 * A class defining the caller context for auditing coarse granularity
38	 * operations.
39	 *
40	 * This class is immutable.
41	 */
42	@InterfaceAudience.Public
43	@InterfaceStability.Evolving
44	public final class CallerContext {
45	  public static final Charset SIGNATURE_ENCODING = StandardCharsets.UTF_8;
46	  /** The caller context.
47	   *
48	   * It will be truncated if it exceeds the maximum allowed length in
49	   * server. The default length limit is
50	   * {@link org.apache.hadoop.fs.CommonConfigurationKeysPublic#HADOOP_CALLER_CONTEXT_MAX_SIZE_DEFAULT}
51	   */
52	  private final String context;
53	
54	  /** The caller's signature for validation.
55	   *
56	   * The signature is optional. The null or empty signature will be abandoned.
57	   * If the signature exceeds the maximum allowed length in server, the caller
58	   * context will be abandoned. The default length limit is
59	   * {@link org.apache.hadoop.fs.CommonConfigurationKeysPublic#HADOOP_CALLER_CONTEXT_SIGNATURE_MAX_SIZE_DEFAULT}
60	   */
61	  private final byte[] signature;
62	
63	  private CallerContext(Builder builder) {
64	    this.context = builder.getContext();
65	    this.signature = builder.getSignature();
66	  }
67	
68	  public String getContext() {
69	    return context;
70	  }
71	
72	  public byte[] getSignature() {
73	    return signature == null ?
74	        null : Arrays.copyOf(signature, signature.length);
75	  }
76	
77	  @InterfaceAudience.Private
78	  public boolean isContextValid() {
79	    return context != null && !context.isEmpty();
80	  }
81	
82	  @Override
83	  public int hashCode() {
84	    return new HashCodeBuilder().append(context).toHashCode();
85	  }
86	
87	  @Override
88	  public boolean equals(Object obj) {
89	    if (obj == null) {
90	      return false;
91	    } else if (obj == this) {
92	      return true;
93	    } else if (obj.getClass() != getClass()) {
94	      return false;
95	    } else {
96	      CallerContext rhs = (CallerContext) obj;
97	      return new EqualsBuilder()
98	          .append(context, rhs.context)
99	          .append(signature, rhs.signature)
100	          .isEquals();
101	    }
102	  }
103	
104	  @Override
105	  public String toString() {
106	    if (!isContextValid()) {
107	      return "";
108	    }
109	    String str = context;
110	    if (signature != null) {
111	      str += ":";
112	      str += new String(signature, SIGNATURE_ENCODING);
113	    }
114	    return str;
115	  }
116	
117	  /** The caller context builder. */
118	  public static final class Builder {
119	    private static final String KEY_VALUE_SEPARATOR = ":";
120	    /**
121	     * The illegal separators include '\t', '\n', '='.
122	     * User should not set illegal separator.
123	     */
124	    private static final Set<String> ILLEGAL_SEPARATORS =
125	        Collections.unmodifiableSet(
126	            new HashSet<>(Arrays.asList("\t", "\n", "=")));
127	    private final String fieldSeparator;
128	    private final StringBuilder sb = new StringBuilder();
129	    private byte[] signature;
130	
131	    public Builder(String context) {
132	      this(context, HADOOP_CALLER_CONTEXT_SEPARATOR_DEFAULT);
133	    }
134	
135	    public Builder(String context, Configuration conf) {
136	      if (isValid(context)) {
137	        sb.append(context);
138	      }
139	      fieldSeparator = conf.get(HADOOP_CALLER_CONTEXT_SEPARATOR_KEY,
140	          HADOOP_CALLER_CONTEXT_SEPARATOR_DEFAULT);
141	      checkFieldSeparator(fieldSeparator);
142	    }
143	
144	    public Builder(String context, String separator) {
145	      if (isValid(context)) {
146	        sb.append(context);
147	      }
148	      fieldSeparator = separator;
149	      checkFieldSeparator(fieldSeparator);
150	    }
151	
152	    /**
153	     * Check whether the separator is legal.
154	     * The illegal separators include '\t', '\n', '='.
155	     * Throw IllegalArgumentException if the separator is Illegal.
156	     * @param separator the separator of fields.
157	     */
158	    private void checkFieldSeparator(String separator) {
159	      if (ILLEGAL_SEPARATORS.contains(separator)) {
160	        throw new IllegalArgumentException("Illegal field separator: "
161	            + separator);
162	      }
163	    }
164	
165	    /**
166	     * Whether the field is valid.
167	     * @param field one of the fields in context.
168	     * @return true if the field is not null or empty.
169	     */
170	    private boolean isValid(String field) {
171	      return field != null && field.length() > 0;
172	    }
173	
174	    public Builder setSignature(byte[] signature) {
175	      if (signature != null && signature.length > 0) {
176	        this.signature = Arrays.copyOf(signature, signature.length);
177	      }
178	      return this;
179	    }
180	
181	    /**
182	     * Get the context.
183	     * For example, the context is "key1:value1,key2:value2".
184	     * @return the valid context or null.
185	     */
186	    public String getContext() {
187	      return sb.length() > 0 ? sb.toString() : null;
188	    }
189	
190	    /**
191	     * Get the signature.
192	     * @return the signature.
193	     */
194	    public byte[] getSignature() {
195	      return signature;
196	    }
197	
198	    /**
199	     * Append new field to the context.
200	     * @param field one of fields to append.
201	     * @return the builder.
202	     */
203	    public Builder append(String field) {
204	      if (isValid(field)) {
205	        if (sb.length() > 0) {
206	          sb.append(fieldSeparator);
207	        }
208	        sb.append(field);
209	      }
210	      return this;
211	    }
212	
213	    /**
214	     * Append new field which contains key and value to the context.
215	     * @param key the key of field.
216	     * @param value the value of field.
217	     * @return the builder.
218	     */
219	    public Builder append(String key, String value) {
220	      if (isValid(key) && isValid(value)) {
221	        if (sb.length() > 0) {
222	          sb.append(fieldSeparator);
223	        }
224	        sb.append(key).append(KEY_VALUE_SEPARATOR).append(value);
225	      }
226	      return this;
227	    }
228	
229	    /**
230	     * Append new field which contains key and value to the context
231	     * if the key is absent.
232	     * @param key the key of field.
233	     * @param value the value of field.
234	     * @return the builder.
235	     */
236	    public Builder appendIfAbsent(String key, String value) {
237	      if (sb.toString().contains(key + KEY_VALUE_SEPARATOR)) {
238	        return this;
239	      }
240	      if (isValid(key) && isValid(value)) {
241	        if (sb.length() > 0) {
242	          sb.append(fieldSeparator);
243	        }
244	        sb.append(key).append(KEY_VALUE_SEPARATOR).append(value);
245	      }
246	      return this;
247	    }
248	
249	    public CallerContext build() {
250	      return new CallerContext(this);
251	    }
252	  }
253	
254	  /**
255	   * The thread local current caller context.
256	   * <p>
257	   * Internal class for defered singleton idiom.
258	   * https://en.wikipedia.org/wiki/Initialization_on_demand_holder_idiom
259	   */
260	  private static final class CurrentCallerContextHolder {
261	    static final ThreadLocal<CallerContext> CALLER_CONTEXT =
262	        new InheritableThreadLocal<>();
263	  }
264	
265	  public static CallerContext getCurrent() {
266	    return CurrentCallerContextHolder.CALLER_CONTEXT.get();
267	  }
268	
269	  public static void setCurrent(CallerContext callerContext) {
270	    CurrentCallerContextHolder.CALLER_CONTEXT.set(callerContext);
271	  }
272	}
